import math

n = int(input())
for i in range(n):
    h = int(input())
    k = int(input())
    if k < 0:
        print("no real solution")
    elif k == 0:
        print(f"x = {h}")
    elif math.isqrt(k) ** 2 == k:
        s = math.isqrt(k)
        print(f"x = {h - s} or x = {h + s}")
    else:
        s = math.sqrt(k)
        print(f"x = {h - s:.6f} or x = {h + s:.6f}")
